'use strict';
(()=>{
 const registry=window.QNPages,routes=window.QNRoutes,root=document.querySelector('#app');let scene='sample';
 const samples=[{id:'demo-publish-1',kind:'TASK',storeId:'demo-store-1',platform:'JD_SHOP',platformName:'京东',storeName:'袜品示例店',title:'纯棉中筒袜 · 发布结果核验',state:'UNKNOWN',priority:'P0',reason:'发布回执中断，原确认与写入锁保留',writeLocked:true,target:'JD-005'},
 {id:'demo-purchase-1',kind:'PURCHASE',storeId:'demo-store-2',platform:'XHS',platformName:'小红书',storeName:'家居示例店',title:'棉质内衣 · 采购草稿',state:'READY',priority:'P2',reason:'按商品明细核对 1688 货源、金额与收货地址',writeLocked:false,target:'PUR-002'},
 {id:'demo-refund-1',kind:'FINANCE',storeId:'demo-store-3',platform:'WECHAT_SHOP',platformName:'微信小店',storeName:'日常示例店',title:'订单售后 · 退款待分配',state:'UNALLOCATED',priority:'P2',reason:'本人按商品明细关联采购单并分配退款',writeLocked:false,target:'FIN-003'}];
 const node=(t,text,cls)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function link(text,id,q={},surface='web'){const a=node('a',text);a.href=routes.hash(id,q,surface);return a;}
 function pageState(){const parts=location.hash.split('/'),surface=parts.includes('pc')?'pc':'web';return {...routes.parse(location.hash,registry,surface),surface};}
 function currentSamples(q,exceptions=false){return (scene==='empty'?[]:samples).filter(s=>(!q.storeId||s.storeId===q.storeId)&&(!q.platform||s.platform===q.platform)&&(!q.kind||s.kind===q.kind)&&(!q.priority||s.priority===q.priority)&&(!exceptions||s.writeLocked||s.state==='FAILED'));}
 function tools(container){const bar=node('div',undefined,'demo-tools');for(const [value,text] of [['sample','演示记录'],['empty','已观察为空'],['error','读取失败']]){const b=node('button',text,value===scene?'primary':'');b.addEventListener('click',()=>{scene=value;render();});bar.append(b);}container.append(bar);}
 function filter(container,p,q,list=false){const form=node('form',undefined,'filters');const choose=(label,name,options)=>{const l=node('label',label),s=node('select');s.name=name;for(const [value,text] of options){const o=node('option',text);o.value=value;s.append(o);}s.value=q[name]||options[0][0];l.append(s);form.append(l);};choose('店铺范围','storeId',[['','示例店铺 · 本人范围'],['demo-store-1','袜品示例店'],['demo-store-2','家居示例店'],['demo-store-3','日常示例店']]);choose('平台','platform',[['','全部平台'],['1688','1688'],['XHS','小红书'],['WECHAT_SHOP','微信小店'],['JD_SHOP','京东']]);if(list){choose('待办类型','kind',[['','全部待处理'],['TASK','执行任务'],['PURCHASE','采购建议'],['FINANCE','费用与退款']]);choose('优先级','priority',[['','全部'],['P0','优先对账'],['P1','异常核查'],['P2','经营待办']]);choose('每页','size',[['20','20 条'],['50','50 条']]);}const b=node('button','查询','primary');form.append(b);form.addEventListener('submit',e=>{e.preventDefault();location.hash=routes.hash(p.id,{...Object.fromEntries(new FormData(form)),page:1},p.surface);});const reset=node('button','重置');reset.type='button';reset.addEventListener('click',()=>{location.hash=routes.hash(p.id,{},p.surface);});form.append(reset);container.append(form);}
 function taskTable(container,items,q,p){if(!items.length){container.append(node('div','当前示例范围无待处理记录。未读取的平台状态仍为待核验。','empty'));return;}const table=node('table'),head=node('tr');for(const label of ['类型 / 店铺','业务对象','原因','状态 / 优先级','操作'])head.append(node('th',label));table.append(head);for(const s of items){const row=node('tr'),first=node('td');first.append(node('strong',s.platformName),node('p',s.storeName,'muted'));const state=node('td');state.append(node('span',s.writeLocked?'UNKNOWN · 锁定':s.state==='READY'?'待本人确认':'待手工分配',s.writeLocked?'pill danger':'pill'),node('p',s.priority,'muted'));const action=node('td');action.append(link(s.writeLocked?'查看原任务':'查看上下文','SYS-009',{objectId:s.id,objectVersion:1,returnTo:location.hash,sourcePage:p.id}));row.append(first,node('td',s.title),node('td',s.reason),state,action);table.append(row);}const wrap=node('div',undefined,'table-wrap');wrap.append(table);container.append(wrap);}
 function dashboard(container,p,q){filter(container,p,q);const metrics=[['执行待处理',scene==='empty'?'0':'1','DASH-002'],['今日新增订单',scene==='empty'?'0':'2','ORD-001'],['待采购建议',scene==='empty'?'0':'1','PUR-001'],['待回填包裹',scene==='empty'?'0':'2','LOG-001'],['已采集完整货源',scene==='empty'?'0':'5','SRC-005'],['设备执行状态','待实机核验','SYS-003']];const grid=node('div',undefined,'grid');for(const [label,value,target] of metrics){const box=node('button',undefined,'metric');box.append(node('small',label),node('b',value),node('span','示例 / 查看详情 →','caption'));box.addEventListener('click',()=>location.hash=routes.hash(target,q));grid.append(box);}container.append(grid,node('p','演示数据 · 本地原型示例 / 非经营统计 · 正式系统数据来自 NAS 数据库与最近 PC 心跳','meta'));
 const cols=node('div',undefined,'columns'),todo=node('section',undefined,'card'),heading=node('div',undefined,'row between');heading.append(node('h2','待本人处理'),link('查看全部','DASH-002',q));todo.append(heading);taskTable(todo,currentSamples(q),q,p);const side=node('div'),platform=node('section',undefined,'card');platform.append(node('h2','平台链路状态'));for(const label of ['1688 → 小红书首链','微信小店','京东 · 首批袜子 / 内衣']){const row=node('div',undefined,'status-row'),text=node('div');row.append(node('span',undefined,'dot warn'));text.append(node('strong',label),node('p','已有开发链路 · 真实样本待统一 SIT'));row.append(text);platform.append(row);}platform.append(node('p','快手后置；每平台每操作独立核验。','muted'));const reminders=node('section',undefined,'card');reminders.append(node('h2','核对提醒'));for(const label of ['登录身份按独立 Profile 核验','采购草稿改价或改地址后须重新确认','售后逐商品关联多采购单','退款金额由本人手工分配'])reminders.append(node('p',label,'muted'));reminders.append(link('异常与锁定记录','DASH-003'));side.append(platform,reminders);cols.append(todo,side);container.append(cols);const flow=node('section',undefined,'card');flow.append(node('h2','经营主链'));const steps=node('div',undefined,'steps');for(const label of ['货源与商品','草稿与本人发布','订单回流','本人确认采购','物流与售后'])steps.append(node('span',label));flow.append(steps,node('p','发布、采购和物流写入须本人确认；支付及平台售后决定由本人处理。','muted'));container.append(flow);
 }
 function todo(container,p,q){filter(container,p,q,p.id==='DASH-002');const card=node('section',undefined,'card');card.append(node('h2',p.id==='DASH-003'?'异常与外部写入锁':'待本人处理'));if(p.id==='DASH-003')card.append(node('p','原确认快照保持不变，仅查看与只读对账；禁止重复发送外部写。','notice warning'));const rows=currentSamples(q,p.id==='DASH-003');taskTable(card,rows,q,p);card.append(node('p',`示例共 ${rows.length} 条 · 每页 ${q.size||20} 条`,'meta'));container.append(card);}
 function taskDetail(container,q){const sample=samples.find(s=>s.id===q.objectId);if(!sample)return false;const card=node('section',undefined,'card');card.append(node('h2',sample.title),node('p',sample.reason,sample.writeLocked?'notice warning':'muted'));const list=node('dl',undefined,'detail-list');for(const [key,value] of [['店铺',sample.storeName],['平台',sample.platformName],['对象版本','1（演示）'],['写入状态',sample.writeLocked?'锁定，保留原确认':'尚未发起写入'],['下一步',sample.writeLocked?'进入只读对账':'核对业务明细']])list.append(node('dt',key),node('dd',value));card.append(list);const actions=node('div',undefined,'business-links');actions.append(link(sample.writeLocked?'进入只读对账':'进入业务工作区',sample.target,{...q}));const back=routes.safeReturn(q.returnTo);if(back){const a=node('a','返回原列表');a.href=back;actions.append(a);}card.append(actions);container.append(card);return true;}
 function specification(container,p,q){if(taskDetail(container,q)&&p.id==='SYS-009')return;const card=node('section',undefined,'card');card.append(node('h2',p.name),node('p','该页面使用当前页面编号和业务边界；本增量完成框架设计。实际独立字段与操作界面在 '+p.phase+' 收口。','notice warning'));const links=node('div',undefined,'business-links');const chains=p.id.startsWith('PC')?[['PC-001','首次配对'],['PC-002','设备状态'],['PC-006','连接与设置'],['PC-007','档案核验']]:[['SRC-001','选择货源'],['PRD-001','商品编辑'],['STORE-004','草稿与发布确认'],['ORD-001','订单明细'],['PUR-002','采购确认'],['LOG-002','物流确认'],['AS-002','售后关联'],['FIN-003','费用与退款分配']];for(const [id,label] of chains)links.append(link(label,id,{},p.surface));card.append(links);container.append(card);
 if(p.id==='PC-001'){const c=node('section',undefined,'card form');c.append(node('h2','首次配对 · 未配对可进入'));for(const [label,placeholder] of [['NAS HTTPS 地址','https://您的NAS地址'],['一次性配对信息','从 NAS 本人配置页导入'],['Chrome / UTP 程序路径','固定 Windows PC 的实际程序']]){const l=node('label',label),input=node('input');input.placeholder=placeholder;l.append(input);c.append(l);}const b=node('button','检查连接（演示）');b.addEventListener('click',()=>{c.append(node('p','原型仅展示向导；实际控制台会核对 HTTPS、版本、设备及独立档案。','notice'));});c.append(b);container.append(c);}
 const fields=p.fields.filter(x=>x.label&&!x.id.endsWith('F-999'));if(fields.length){const info=node('section',undefined,'card');info.append(node('h2','页面字段基线'));const table=node('table'),head=node('tr');head.append(node('th','字段'),node('th','当前值'),node('th','口径'));table.append(head);for(const f of fields.slice(0,12)){const row=node('tr');row.append(node('td',f.label),node('td','待读取 / 待核验'),node('td','本人范围、真实对象与来源版本'));table.append(row);}info.append(table);const details=node('details'),summary=node('summary','设计与实现记录');details.append(summary,node('p',`${p.id} · ${p.frontend} · 后续 ${p.phase} · 实样待统一 SIT`,'muted'));info.append(details);container.append(info);}
 }
 function render(){const r=pageState(),p=registry.pages.find(x=>x.id===r.pageId);root.replaceChildren();document.body.classList.toggle('pc-surface',r.surface==='pc');if(!p){root.append(node('div','页面不存在，请返回工作台。','empty'),link('工作台','DASH-001'));return;}document.title=`青鸟 · ${p.name} · V9.1.1 W8R2A`;const shell=node('div',undefined,'shell'),aside=node('aside'),brand=node('div',undefined,'brand'),img=node('img');img.src='./assets/qingniao-A-'+(p.surface==='pc'?'inverse':'ink')+'.svg';img.alt='青鸟';const title=node('div','青鸟');title.append(node('small',p.surface==='pc'?'固定 Windows PC':'个人经营工作台'));brand.append(img,title);aside.append(brand);const nav=node('nav');nav.setAttribute('aria-label','主导航');let group='';const ms=p.surface==='pc'?registry.pages.filter(x=>x.surface==='pc').map(x=>({group:'本机执行工作区',name:x.name,pageId:x.id,pages:[x.id]})):registry.menus;for(const m of ms){if(m.group!==group){group=m.group;nav.append(node('div',group,'nav-group'));}const a=link(m.name,m.pageId,{},p.surface);a.classList.toggle('active',m.pages.includes(p.id));nav.append(a);}aside.append(nav);const foot=node('div',undefined,'aside-footer');foot.append(node('div','V9.1.1 / W8R2A · 交互原型'),link(p.surface==='pc'?'NAS 工作台':'PC 客户端',p.surface==='pc'?'DASH-001':'PC-001',{},p.surface==='pc'?'web':'pc'));aside.append(foot);
 const main=node('main'),header=node('header');header.append(node('strong',p.name),node('span','演示数据 / 待平台验证','pill warning'),node('span','本人 · 私有经营空间','identity'));const legacy=node('a','历史 V3.9');legacy.href='./legacy/#/'+p.surface+'/'+(p.surface==='pc'?'PC-001':'DASH-001');header.append(legacy);main.append(header);const workspace=node('div',undefined,'workspace'),heading=node('div',undefined,'page-title'),text=node('div');text.append(node('span','青鸟 / '+p.group,'eyebrow'),node('h1',p.name),node('p','需求 V9.1.1 + 京东与安装增量 · NAS 为唯一业务真源'));heading.append(text);workspace.append(heading);const menu=registry.menus.find(m=>m.pages.includes(p.id)),tabs=node('div',undefined,'page-tabs');for(const id of menu?.pages||[]){const page=registry.pages.find(x=>x.id===id);if(page)tabs.append(link(page.name,id,{},p.surface));}workspace.append(tabs);const banner=node('p','原型场景为演示；W8R2A 已接通实际系统工作台、待处理和异常第一版。其余页面按台账继续收口，实样保持待验证。','notice');workspace.append(banner);tools(workspace);
 if(scene==='error'){const error=node('section',undefined,'card');error.append(node('h2','本地读取失败（演示）'),node('p','保留原路由与筛选，数据未更新。未知结果和写入锁不会因刷新解除。','notice error'));const b=node('button','重新读取');b.addEventListener('click',()=>{scene='sample';render();});error.append(b);workspace.append(error);}else if(p.id==='DASH-001')dashboard(workspace,p,r.query);else if(['DASH-002','DASH-003'].includes(p.id))todo(workspace,p,r.query);else specification(workspace,p,r.query);
 const footer=node('footer');footer.id='page-footer';footer.append(node('span','本人确认 / 独立档案 / UNKNOWN 只读恢复'),node('span','青鸟 V9.1.1 · W8R2A'));workspace.append(footer);main.append(workspace);shell.append(aside,main);root.append(shell);
 }
 window.addEventListener('hashchange',render);if(!location.hash)history.replaceState(null,'',routes.hash('DASH-001'));render();
})();
